--
-- ToDo 7.7.4  - Enterprise Automatic/Estate Vehicle Class Management 
--

-- New Vehicle Classes

--
-- Vehicle Class Prices
--
select 0, 999, 999, now(), now(), vc2.id, vcp.age, vcp.start_date, vcp.price + 10.00
from vehicle_class vc, vehicle_class vc2, vehicle_class_price vcp
where right(vc2.name, 4) = 'ESTA'
   and left(vc2.name, char_length(vc2.name)-4) = vc.name
   and vc.id = vcp.vehicle_class_id;

select 0, 999, 999, now(), now(), vc2.id, vcp.age, vcp.start_date, vcp.price + 5.00
from vehicle_class vc, vehicle_class vc2, vehicle_class_price vcp
where right(vc2.name, 3) = 'EST'
   and left(vc2.name, char_length(vc2.name)-3) = vc.name
   and vc.id = vcp.vehicle_class_id;


select 0, 999, 999, now(), now(), vc2.id, vcp.age, vcp.start_date, vcp.price + 5.00
from vehicle_class vc, vehicle_class vc2, vehicle_class_price vcp
where right(vc2.name, 1) = 'A' and right(vc2.name, 4) != 'ESTA'
   and left(vc2.name, char_length(vc2.name)-1) = vc.name
   and vc.id = vcp.vehicle_class_id;

--
-- Vehicle Class Ceilings
--
select 0, 999, 999, now(), now(), vc2.id, vcc.insurer_id, vcc.hire_net_ceiling, vcc.repair_net_ceiling
from vehicle_class vc, vehicle_class vc2, vehicle_class_ceiling vcc
where vcc.vehicle_class_id = vc.id
  and right(vc2.name, 4) = 'ESTA'
  and left(vc2.name, char_length(vc2.name)-4) = vc.name;
  
select 0, 999, 999, now(), now(), vc2.id, vcc.insurer_id, vcc.hire_net_ceiling, vcc.repair_net_ceiling
from vehicle_class vc, vehicle_class vc2, vehicle_class_ceiling vcc
where vcc.vehicle_class_id = vc.id
  and right(vc2.name, 3) = 'EST'
  and left(vc2.name, char_length(vc2.name)-3) = vc.name;
  
select 0, 999, 999, now(), now(), vc2.id, vcc.insurer_id, vcc.hire_net_ceiling, vcc.repair_net_ceiling
from vehicle_class vc, vehicle_class vc2, vehicle_class_ceiling vcc
where vcc.vehicle_class_id = vc.id
  and right(vc2.name, 1) = 'A' and right(vc2.name, 4) != 'ESTA'
  and left(vc2.name, char_length(vc2.name)-1) = vc.name;
  

--
-- End Of ToDo 7.7.4
